```js
const $ = (sel) => document.querySelector(sel);

const state = {
  cpu: 64,
  mem: { used: 12.8, total: 32 },
  disk: { used: 248, total: 1000 },
  net: { in: 1.24, out: 0.43 },
  uptime: { d: 14, h: 6, m: 21, s: 0 },
  load: [0.42, 0.38, 0.41],
  cpuHist: [],
  memHist: [],
  procs: [
    { name: 'postgres', pid: 1422, cpu: 12.4, mem: 4.2 },
    { name: 'redis-server', pid: 1487, cpu: 6.1, mem: 2.8 },
    { name: 'nginx: worker', pid: 1502, cpu: 4.8, mem: 1.1 },
    { name: 'node app.js', pid: 1634, cpu: 18.2, mem: 6.4 },
    { name: 'dockerd', pid: 1108, cpu: 2.1, mem: 1.6 },
    { name: 'sshd', pid: 982, cpu: 0.4, mem: 0.3 },
  ],
  services: [
    { name: 'nginx', port: 80, status: 'up', up: '14d 06h' },
    { name: 'postgres', port: 5432, status: 'up', up: '14d 06h' },
    { name: 'redis', port: 6379, status: 'up', up: '2d 11h' },
    { name: 'docker', port: 2375, status: 'up', up: '14d 06h' },
    { name: 'fail2ban', port: '-', status: 'warn', up: '14d 05h' },
    { name: 'sshd', port: 22, status: 'up', up: '14d 06h' },
  ],
};

function drift(v, amount, min, max) {
  v += (Math.random() - 0.5) * amount;
  return Math.max(min, Math.min(max, v));
}

function tick() {
  state.s++;
  if (state.s >= 60) { state.s = 0; state.m++; }
  if (state.m >= 60) { state.m = 0; state.h++; }
  if (state.h >= 24) { state.h = 0; state.d++; }

  state.cpu = +drift(state.cpu, 8, 5, 95).toFixed(0);
  state.mem.used = +drift(state.mem.used, 0.4, 2, state.mem.total - 1).toFixed(1);
  state.disk.used = +drift(state.disk.used, 2, 10, state.disk.total - 50).toFixed(0);
  state.net.in = +drift(state.net.in, 0.3, 0.05, 8).toFixed(2);
  state.net.out = +drift(state.net.out, 0.2, 0.02, 5).toFixed(2);
  state.load = state.load.map(v => +drift(v, 0.06, 0.05, 4).toFixed(2));

  state.cpuHist.push(state.cpu);
  if (state.cpuHist.length > 30) state.cpuHist.shift();
  state.memHist.push(state.mem.used);
  if (state.memHist.length > 30) state.memHist.shift();

  state.procs = state.procs.map(p => ({
    ...p,
    cpu: +drift(p.cpu, 3, 0.1, 40).toFixed(1),
    mem: +drift(p.mem, 0.3, 0.1, 12).toFixed(1),
  })).sort((a,b) => b.cpu - a.cpu);
}

function render() {
  // cards
  $('#cpuVal').textContent = state.cpu;
  $('#cpuBar').style.width = state.cpu + '%';
  $('#memVal').textContent = state.mem.used.toFixed(1);
  $('#memBar').style.width = (state.mem.used/state.mem.total*100).toFixed(1) + '%';
  $('#diskVal').textContent = state.disk.used;
  $('#diskBar').style.width = (state.disk.used/state.disk.total*100).toFixed(1) + '%';
  $('#netVal').textContent = state.net.in.toFixed(2);
  // chart
  drawSpark('#cpuSpark', state.cpuHist, '#00f0ff');
  drawSpark('#memSpark', state.memHist, '#ff2d95', state.mem.total);
  // load
  $('#loadVal').textContent = state.load.join('  ');
  $('#uptimeVal').textContent = `${String(state.d).padStart(2,'0')}d ${String(state.h).padStart(2,'0')}h ${String(state.m).padStart(2,'0')}m`;
  // procs
  // services
  // clock
  $('#clock').textContent = nowClock();
}
```

