```js
function drawSpark(sel, data, color, max) {
  const svg = document.querySelector(sel);
  const w = 600, h = 140, p = 8;
  const n = data.length;
  if (n < 2) return;
  const m = max || Math.max(...data) * 1.1 || 100;
  const x = i => p + (i / (n - 1)) * (w - p * 2);
  const y = v => h - p - (v / m) * (h - p * 2);
  let pts = data.map((v,i) => `${x(i)},${y(v)}`).join(' ');
  // area
  const area = `${pts} ${x(n-1)},${h-p} ${x(0)},${h-p}`;
  svg.innerHTML = `
    <defs>
      <linearGradient id="g" x1="0" x2="0" y1="0" y2="1">
        <stop offset="0%" stop-color="${color}" stop-opacity="0.35"/>
        <stop offset="100%" stop-color="${color}" stop-opacity="0"/>
      </linearGradient>
    </defs>
    <polygon class="area" points="${area}" fill="url(#g)"/>
    <polyline class="line" points="${pts}" />
    <circle cx="${x(n-1)}" cy="${y(data[n-1])}" r="2.5" fill="${color}" style="filter: drop-shadow(0 0 4px ${color})"/>
  `;
}
```

