```js
/* NODE // 07 — server telemetry dashboard */
const $ = (sel) => document.querySelector(sel);
const fmt = (n, d=0) => Number(n).toFixed(d);

const state = {
  cpu: 64,
  mem: { used: 12.8, total: 32 },
  disk: { used: 248, total: 1000 },
  net: { in: 1.24, out: 0.43 },
  uptime: { d: 14, h: 6, m: 21, s: 0 },
  load: [0.42, 0.38, 0.41],
  cpuHist: [],
  memHist: [],
  procs: [
    { name: 'postgres', pid: 1422, cpu: 12.4, mem: 4.2 },
    { name: 'redis-server', pid: 1487, cpu: 6.1, mem: 2.8 },
    { name: 'nginx: worker', pid: 1502, cpu: 4.8, mem: 1.1 },
    { name: 'node app.js', pid: 1634, cpu: 18.2, mem: 6.4 },
    { name: 'dockerd', pid: 1108, cpu: 2.1, mem: 1.6 },
    { name: 'sshd', pid: 982, cpu: 0.4, mem: 0.3 },
  ],
  services: [
    { name: 'nginx', port: 80, status: 'up', up: '14d 06h' },
    { name: 'postgres', port: 5432, status: 'up', up: '14d 06h' },
    { name: 'redis', port: 6379, status: 'up', up: '2d 11h' },
    { name: 'docker', port: 2375, status: 'up', up: '14d 06h' },
    { name: 'fail2ban', port: '-', status: 'warn', up: '14d 05h' },
    { name: 'sshd', port: 22, status: 'up', up: '14d 06h' },
  ],
};

const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
const drift = (v, amt, a, b) => clamp(v + (Math.random()-0.5)*amt, a, b);

function tick() {
  state.uptime.s++;
  if (state.uptime.s >= 60) { state.uptime.s = 0; state.uptime.m++; }
  if (state.uptime.m >= 60) { state.uptime.m = 0; state.uptime.h++; }
  if (state.uptime.h >= 24) { state.uptime.h = 0; state.uptime.d++; }

  state.cpu = +drift(state.cpu, 8, 5, 95).toFixed(0);
  state.mem.used = +drift(state.mem.used, 0.4, 2, state.mem.total - 1).toFixed(1);
  state.disk.used = +drift(state.disk.used, 2, 10, state.disk.total - 50).toFixed(0);
  state.net.in = +drift(state.net.in, 0.3, 0.05, 8).toFixed(2);
  state.net.out = +drift(state.net.out, 0.2, 0.02, 5).toFixed(2);
  state.load = state.load.map(v => +drift(v, 0.06, 0.05, 4).toFixed(2));

  state.cpuHist.push(state.cpu);
  if (state.cpuHist.length > 30) state.cpuHist.shift();
  state.memHist.push(state.mem.used);
  if (state.memHist.length > 30) state.memHist.shift();

  state.procs = state.procs.map(p => ({
    ...p,
    cpu: +drift(p.cpu, 3, 0.1, 40).toFixed(1),
    mem: +drift(p.mem, 0.3, 0.1, 12).toFixed(1),
  })).sort((a,b) => b.cpu - a.cpu);
}

function drawSpark(sel, data, color, max) {
  const svg = $(sel);
  const W = 600, H = 150, P = 8;
  const n = data.length;
  if (n < 2) { svg.innerHTML = ''; return; }
  const m = max || Math.max(80, ...data) * 1.15;
  const x = i => P + (i/(n-1)) * (W - P*2);
  const y = v => H - P - (v/m) * (H - P*2);
  const pts = data.map((v,i) => `${x(i)|0},${y(v)|0}`).join(' ');
  const area = `${pts} ${x(n-1)|0},${H-P} ${x(0)|0},${H-P}`;
  const last = data[n-1];
  // grid lines
  let grid = '';
  for (let g of [0.25, 0.5, 0.75, 1]) {
    const yy = y(m*g);
    grid += `<line x1="${P}" y1="${yy}" x2="${W-P}" y2="${yy}" stroke="#1d1d2b" stroke-dasharray="2 5"/>`;
  }
  // threshold at 80%
  const thr = `<line x1="${P}" y1="${y(80)}" x2="${W-P}" y2="${y(80)}" stroke="#ff2d95" stroke-opacity=".4" stroke-dasharray="4 4"/>`;
  svg.innerHTML = `
    ${grid}${thr}
    <polygon points="${area}" fill="${color}" fill-opacity="0.18"/>
    <polyline points="${pts}" fill="none" stroke="${color}" stroke-width="1.6" stroke-linejoin="round"/>
    <circle cx="${x(n-1)|0}" cy="${y(last)|0}" r="2.6" fill="${color}" style="filter: drop-shadow(0 0 5px ${color})"/>
    <text x="${x(n-1)|0 - 8}" y="${y(last)|0 - 10}" fill="${color}" font-family="ui-monospace,monospace" font-size="10">${last}${color==='#ff2d95'?' GB':''}${color==='#00f0ff'?'%':''}</text>
  `;
}
```

