function render() {
  // CPU card
  $('#cpuVal').textContent = state.cpu;
  $('#cpuVal').style.color = state.cpu > 80 ? '#ff3b3b' : state.cpu > 60 ? '#ffb000' : '#00f0ff';
  $('#cpuBar').style.width = state.cpu + '%';
  $('#cpuFoot').textContent = `load ${state.load[0].toFixed(2)} · 4 cores`;

  $('#memVal').textContent = state.mem.used.toFixed(1);
  $('#memBar').style.width = (state.mem.used/state.mem.total*100).toFixed(1) + '%';
  $('#memFoot').textContent = `${(state.mem.total - state.mem.used).toFixed(1)} free of ${state.mem.total} GB`;

  $('#diskVal').textContent = state.disk.used;
  $('#diskBar').style.width = (state.disk.used/state.disk.total*100).toFixed(1) + '%';
  $('#diskFoot').textContent = `${state.disk.total - state.disk.used} GB free`;

  $('#netVal').textContent = state.net.in.toFixed(2);
  $('#netFoot').textContent = `tx ${state.net.out.toFixed(2)} Gb/s`;

  drawSpark('#cpuSpark', state.cpuHist, '#00f0ff', 100, '%');
  drawSpark('#memSpark', state.memHist, '#ff2d95', state.mem.total, ' GB');

  $('#loadVal').textContent = state.load.map(v => v.toFixed(2)).join('  ');
  $('#uptimeVal').textContent = `${String(state.uptime.d).padStart(2,'0')}d ${String(state.uptime.h).padStart(2,'0')}h ${String(state.uptime.m).padStart(2,'0')}m`;
  $('#netInVal').textContent = state.net.in.toFixed(2);
  $('#netOutVal').textContent = state.net.out.toFixed(2);

  const body = $('#procBody');
  body.innerHTML = state.procs.map(p => `
    <tr>
      <td class="name">${p.name}</td>
      <td>${p.pid}</td>
      <td>
        <div class="mini-bar"><i style="width:${Math.min(100,p.cpu*3)}%;background:${p.cpu>15?'#ff3b3b':p.cpu>8?'#ffb000':'#00f0ff'}"></i></div>
        <span style="margin-left:8px">${p.cpu.toFixed(1)}</span>
      </td>
      <td>${p.mem.toFixed(1)}</td>
    </tr>`).join('');

  $('#servicesList').innerHTML = state.services.map(s => {
    const cls = s.status === 'up' ? '' : s.status === 'warn' ? 'warn' : 'crit';
    const color = s.status === 'up' ? '#39ff14' : s.status === 'warn' ? '#ffb000' : '#ff3b3b';
    return `
      <div class="service">
        <div class="left">
          <span class="dot ${cls}" style="box-shadow:0 0 8px ${color}, 0 0 16px ${color}44"></span>
          <span class="name">${s.name}</span>
          <span class="port">:${s.port}</span>
        </div>
        <div class="right">
          <div class="uptime">${s.up}</div>
          <div class="status" style="color:${color}">${s.status}</div>
        </div>
      </div>`;
  }).join('');

  $('#syncTime').textContent = nowClock();
}

function nowClock() {
  const d = new Date();
  return String(d.getHours()).padStart(2,'0') + ':' + String(d.getMinutes()).padStart(2,'0') + ':' + String(d.getSeconds()).padStart(2,'0');
}

function clockTick() {
  $('#clock').textContent = nowClock();
}
