args.content:
:root {
  --bg: #06080f;
  --bg-2: #0a0e1a;
  --neon-cyan: #00e5ff;
  --neon-magenta: #ff2d95;
  --neon-lime: #a3ff12;
  --neon-amber: #ffb300;
  --grid-line: rgba(0, 229, 255, 0.08);
  --text: #d8f4ff;
  --text-dim: #5f7d92;
  --border: rgba(0, 229, 255, 0.25);
  --glow: 0 0 8px rgba(0, 229, 255, 0.55);
  --font: "Courier New", ui-monospace, "SFMono-Regular", Menlo, monospace;
}

* { margin: 0; padding: 0; box-sizing: border-box; }

body {
  background: var(--bg);
  color: var(--text);
  font-family: var(--font);
  min-height: 100vh;
  overflow-x: hidden;
  position: relative;
}

/* --- backdrop grid + scanlines --- */
.grid-bg {
  position: fixed;
  inset: 0;
  background-image:
    linear-gradient(var(--grid-line) 1px, transparent 1px),
    linear-gradient(90deg, var(--grid-line) 1px, transparent 1px);
  background-size: 48px 48px;
  pointer-events: none;
  z-index: 0;
}
.scanlines {
  position: fixed;
  inset: 0;
  background: repeating-linear-gradient(
    0deg,
    transparent 0,
    transparent 2px,
    rgba(0, 229, 255, 0.02) 3px
  );
  pointer-events: none;
  z-index: 1;
}

main, .topbar { position: relative; z-index: 2; }

/* --- top bar --- */
.topbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 14px 22px;
  border-bottom: 1px solid var(--border);
  background: linear-gradient(90deg, rgba(0,229,255,0.06), transparent 40%, rgba(255,45,149,0.06));
}
.brand { display: flex; align-items: baseline; gap: 10px; }
.logo {
  color: var(--neon-magenta);
  text-shadow: 0 0 10px var(--neon-magenta);
  font-size: 18px;
}
.brand-name {
  font-size: 20px;
  font-weight: bold;
  letter-spacing: 6px;
  color: var(--neon-cyan);
  text-shadow: var(--glow);
}
.brand-sub {
  font-size: 11px;
  letter-spacing: 3px;
  color: var(--text-dim);
}
.clock {
  font-size: 18px;
  letter-spacing: 3px;
  color: var(--neon-lime);
  text-shadow: 0 0 8px rgba(163,255,18,0.5);
}
.status { display: flex; align-items: center; gap: 8px; }
.status-text {
  font-size: 11px;
  letter-spacing: 2px;
  color: var(--neon-lime);
}
.dot {
  width: 9px; height: 9px;
  border-radius: 50%;
  display: inline-block;
}
.dot.live {
  background: var(--neon-lime);
  box-shadow: 0 0 10px var(--neon-lime);
  animation: pulse 1.6s infinite;
}
@keyframes pulse {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.35; }
}

main { padding: 22px; max-width: 1400px; margin: 0 auto; }

/* --- stat cards --- */
.stat-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px;
  margin-bottom: 18px;
}
.card {
  position: relative;
  background: var(--bg-2);
  border: 1px solid var(--border);
  padding: 16px;
  clip-path: polygon(0 0, calc(100% - 16px) 0, 100% 16px, 100% 100%, 16px 100%, 0 calc(100% - 16px));
  transition: border-color 0.2s, box-shadow 0.2s;
}
.card::before {
  content: "";
  position: absolute;
  top: 0; left: 0; right: 0;
  height: 2px;
  background: var(--accent, var(--neon-cyan));
  box-shadow: 0 0 10px var(--accent, var(--neon-cyan));
}
.card[data-stat="cpu"]  { --accent: var(--neon-cyan); }
.card[data-stat="mem"]  { --accent: var(--neon-magenta); }
.card[data-stat="disk"] { --accent: var(--neon-lime); }
.card[data-stat="net"]  { --accent: var(--neon-amber); }
.card:hover {
  border-color: var(--accent);
  box-shadow: 0 0 18px rgba(0,229,255,0.12), inset 0 0 24px rgba(0,229,255,0.05);
}
.card-head {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  margin-bottom: 14px;
}
.card-label {
  font-size: 11px;
  letter-spacing: 3px;
  color: var(--text-dim);
}
.card-value {
  font-size: 26px;
  font-weight: bold;
  color: var(--accent);
  text-shadow: 0 0 12px var(--accent);
  letter-spacing: 1px;
}
.bar {
  height: 8px;
  background: rgba(255,255,255,0.05);
  border: 1px solid rgba(0,229,255,0.15);
  position: relative;
  overflow: hidden;
}
.bar-fill {
  height: 100%;
  width: 0%;
  background: var(--accent);
  box-shadow: 0 0 12px var(--accent);
  transition: width 0.5s cubic-bezier(0.2, 0.8, 0.2, 1);
}
.card-foot {
  display: flex;
