// NEXUS server telemetry — simulated data engine.
// Swap `tick()` body with a fetch to your real endpoint to go live.

const state = {
  cpu: 18,
  cores: 8,
  memUsed: 6.2,
  memTotal: 16,
  diskR: 24, diskW: 9,
  net: 142,
  load1: 0.4, load5: 0.5, load15: 0.6,
  upSec: 14 * 86400 + 7 * 3600 + 42 * 60 + 11,
  latency: 12,
  procs: []
};

const PROC_NAMES = ["node", "nginx", "postgres", "redis", "chromium", "dockerd", "sshd", "kubelet", "prometheus", "go-agent", "caddy", "grafana"];
const USERS = ["root", "svc", "www", "db", "deploy"];

function rand(min, max) { return Math.random() * (max - min) + min; }
function clamp(v, a, b) { return Math.min(b, Math.max(a, v)); }

// Seed a process table
for (let i = 0; i < 6; i++) {
  state.procs.push({
    pid: Math.floor(rand(200, 60000)),
    user: USERS[i % USERS.length],
    name: PROC_NAMES[i % PROC_NAMES.length],
    cpu: rand(1, 40),
    mem: rand(2, 28)
  });
}

function jitter(v, amt, lo, hi) { return clamp(v + rand(-amt, amt), lo, hi); }

function tick() {
  // CPU: mostly smooth with occasional spikes
  if (Math.random() < 0.06) state.cpu = clamp(state.cpu + rand(25, 55), 0, 100);
  state.cpu = jitter(state.cpu, 9, 2, 100);

  // Memory: slow drift upward, occasional GC drop
  state.memUsed = jitter(state.memUsed, 0.15, 4, state.memTotal - 1);
  if (Math.random() < 0.08) state.memUsed -= rand(1, 3);
  state.memUsed = clamp(state.memUsed, 4, state.memTotal);

  // Disk I/O
  state.diskR = jitter(state.diskR, 30, 0, 900);
  state.diskW = jitter(state.diskW, 15, 0, 500);

  // Network: spiky
  state.net = Math.random() < 0.12 ? rand(600, 2400) : jitter(state.net, 220, 5, 3200);

  // Load
  state.load1 = jitter(state.load1, 0.15, 0, state.cores * 2);
  state.load5 = jitter(state.load5, 0.08, 0, state.cores * 2);
  state.load15 = jitter(state.load15, 0.03, 0, state.cores * 2);

  state.upSec += 2;
  state.latency = jitter(state.latency, 6, 1, 180);

  // Process table: shuffle a bit, rebalance
  state.procs.forEach(p => {
    p.cpu = jitter(p.cpu, 8, 0, 95);
    p.mem = jitter(p.mem, 2, 0.5, 60);
  });
  if (Math.random() < 0.3) {
    const idx = Math.floor(rand(0, state.procs.length));
    state.procs[idx] = {
      pid: Math.floor(rand(200, 60000)),
      user: USERS[Math.floor(rand(0, USERS.length))],
      name: PROC_NAMES[Math.floor(rand(0, PROC_NAMES.length))],
      cpu: rand(1, 40),
      mem: rand(2, 28)
    };
  }
  state.procs.sort((a, b) => b.cpu - a.cpu);
  state.procs = state.procs.slice(0, 5);
}

function fmtUptime(s) {
  const d = Math.floor(s / 86400);
  const h = Math.floor((s % 86400) / 3600);
  const m = Math.floor((s % 3600) / 60);
  return `${d}d ${h}h ${m}m`;
}
function fmtClock() {
  const n = new Date();
  const p = x => String(x).padStart(2, "0");
  return `${p(n.getHours())}:${p(n.getMinutes())}:${p(n.getSeconds())}`;
}

const $ = id => document.getElementById(id);
function bar(el, pct) { el.style.width = clamp(pct, 0, 100).toFixed(1) + "%"; }

function render() {
  $("val-cpu").textContent = state.cpu.toFixed(2);
  bar($("bar-cpu"), state.cpu);
  $("cores").textContent = state.cores;

  $("val-mem").textContent = state.memUsed.toFixed(1) + " GB";
  bar($("bar-mem"), (state.memUsed / state.memTotal) * 100);
  $("mem-total").textContent = state.memTotal + " GB";

  const diskTotal = state.diskR + state.diskW;
  $("val-disk").textContent = diskTotal.toFixed(0) + " MB/s";
  bar($("bar-disk"), (diskTotal / 900) * 100);
  $("disk-label").textContent = `r ${state.diskR.toFixed(0)} / w ${state.diskW.toFixed(0)}`;

  $("val-net").textContent = state.net.toFixed(0) + " Mb/s";
  bar($("bar-net"), (state.net / 3200) * 100);

  $("clock").textContent = fmtClock();
  $("sys-up").textContent = fmtUptime(state.upSec);
  $("sys-load").textContent =
    `${state.load1.toFixed(2)} ${state.load5.toFixed(2)} ${state.load15.toFixed(2)}`;
  $("latency").textContent = state.latency.toFixed(0) + "ms";

  const body = $("proc-body");
  body.innerHTML = state.procs.map(p =>
    `<tr><td>${p.pid}</td><td>${p.user}</td><td>${p.name}</td>` +
    `<td>${p.cpu.toFixed(1)}</td><td>${p.mem.toFixed(1)}</td></tr>`
  ).join("");
}

setInterval(() => { tick(); render(); }, 2000);
render();

