// NEXUS telemetry — pulls live stats from the local server.
const API = "/api/stats";

function fmt(n, d = 1) {
  if (n >= 1000) return (n / 1024).toFixed(0) + "G";
  return n.toFixed(d);
}

function colorize(v, max, accent) {
  const pct = Math.min(v / max, 1);
  const r = Math.round(255 * pct);
  const g = Math.round(200 * (1 - pct));
  return `rgba(${r},${g},60,0.9)`;
}

async function tick() {
  let s;
  try {
    const r = await fetch(API);
    s = await r.json();
  } catch {
    return; // server not up yet — keep last frame
  }

  // CPU card
  const cpuPct = s.cpu_used;
  document.getElementById("cpu-val").textContent = cpuPct.toFixed(1);
  document.getElementById("cpu-bar").style.width = Math.min(cpuPct, 100) + "%";
  document.getElementById("cpu-foot").textContent =
    `${s.cpu_cores} cores · load ${s.load[0]}`;

