}

const $ = id => document.getElementById(id);
function bar(el, pct) { el.style.width = clamp(pct, 0, 100).toFixed(1) + "%"; }

function render() {
  $("val-cpu").textContent = state.cpu.toFixed(2);
  bar($("bar-cpu"), state.cpu);
  $("cores").textContent = state.cores;

  $("val-mem").textContent = state.memUsed.toFixed(1) + " GB";
  bar($("bar-mem"), (state.memUsed / state.memTotal) * 100);
  $("mem-total").textContent = state.memTotal + " GB";

  const diskTotal = state.diskR + state.diskW;
  $("val-disk").textContent = diskTotal.toFixed(0) + " MB/s";
  bar($("bar-disk"), (diskTotal / 900) * 100);
  $("disk-label").textContent = `r ${state.diskR.toFixed(0)} / w ${state.diskW.toFixed(0)}`;

  $("val-net").textContent = state.net.toFixed(0) + " Mb/s";
  bar($("bar-net"), (state.net / 3200) * 100);

  $("clock").textContent = fmtClock();
  $("sys-up").textContent = fmtUptime(state.upSec);
  $("sys-load").textContent =
    `${state.load1.toFixed(2)} ${state.load5.toFixed(2)} ${state.load15.toFixed(2)}`;
  $("latency").textContent = state.latency.toFixed(0) + "ms";

  const body = $("proc-body");
  body.innerHTML = state.procs.map(p =>
    `<tr><td>${p.pid}</td><td>${p.user}</td><td>${p.name}</td>` +
