def read_cpu():
    """Actual CPU busy % over a 1s sample from /proc/stat."""
    cores = os.cpu_count() or 1
    before = _cpu_times()
    if not before:
        return cores, 0.0
    time.sleep(1)
    after = _cpu_times()
    if not after:
        return cores, 0.0
